-- Dedicated Digital Documents project. No existing application tables are changed.
create table public.dd_insurers (id uuid primary key, name text not null);
create table public.dd_catalog (id uuid primary key, insurer_id uuid not null references public.dd_insurers(id), metadata jsonb not null);
create table public.dd_connections (
  user_id uuid not null references auth.users(id) on delete cascade,
  insurer_id uuid not null references public.dd_insurers(id),
  status text not null check (status in ('active', 'disconnected')),
  consent_at timestamptz not null default now(), last_sync_at timestamptz,
  primary key(user_id, insurer_id)
);
create table public.dd_consent_events (
  id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade,
  insurer_id uuid not null references public.dd_insurers(id), action text not null check(action in ('granted','revoked')),
  version text not null default '1.0', locale text not null check(locale in ('de','en')),
  consent_text text not null, created_at timestamptz not null default now()
);
create table public.dd_documents (
  user_id uuid not null references auth.users(id) on delete cascade,
  document_id uuid not null references public.dd_catalog(id), metadata jsonb not null,
  imported_at timestamptz not null default now(), read_at timestamptz,
  primary key(user_id, document_id)
);
alter table public.dd_insurers enable row level security;
alter table public.dd_catalog enable row level security;
alter table public.dd_connections enable row level security;
alter table public.dd_consent_events enable row level security;
alter table public.dd_documents enable row level security;
create policy insurers_read on public.dd_insurers for select to authenticated using(true);
-- Catalog is only accessible inside security-definer import functions.
create policy own_connections on public.dd_connections for select to authenticated using((select auth.uid()) = user_id);
create policy own_consents on public.dd_consent_events for select to authenticated using((select auth.uid()) = user_id);
create policy own_documents on public.dd_documents for select to authenticated using((select auth.uid()) = user_id);
create policy read_own_documents on public.dd_documents for update to authenticated using((select auth.uid()) = user_id) with check((select auth.uid()) = user_id);
revoke all on public.dd_insurers, public.dd_catalog, public.dd_connections, public.dd_consent_events, public.dd_documents from anon, authenticated;
grant select on public.dd_insurers, public.dd_connections, public.dd_consent_events, public.dd_documents to authenticated;
grant update(read_at) on public.dd_documents to authenticated;

create function public.dd_connect(p_insurer uuid, p_locale text) returns void
language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid(); wording text;
begin
  if actor is null then raise exception 'UNAUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 0));
  if p_locale is null or p_locale not in ('de','en') or not exists(select 1 from public.dd_insurers where id = p_insurer) then raise exception 'INVALID_INPUT'; end if;
  if exists(select 1 from public.dd_connections where user_id = actor and insurer_id = p_insurer and status = 'active') then return; end if;
  wording := case when p_locale = 'de' then 'Ich erlaube FRIDA Digital Documents, meine Beispieldokumente bei diesem Demo-Versicherer abzurufen und in meinem Sandbox-Postfach zu speichern. Ich kann die Verbindung jederzeit trennen. Bereits abgerufene Dokumente bleiben im Postfach.' else 'I allow FRIDA Digital Documents to retrieve my sample documents from this demo insurer and store them in my sandbox inbox. I can disconnect at any time. Previously retrieved documents remain in my inbox.' end;
  insert into public.dd_connections(user_id, insurer_id, status, consent_at) values(actor, p_insurer, 'active', now())
  on conflict(user_id, insurer_id) do update set status = 'active', consent_at = now();
  insert into public.dd_consent_events(user_id, insurer_id, action, locale, consent_text) values(actor, p_insurer, 'granted', p_locale, wording);
end; $$;

create function public.dd_import(p_insurer uuid, p_documents uuid[]) returns void
language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'UNAUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 0));
  if not exists(select 1 from public.dd_connections where user_id = actor and insurer_id = p_insurer and status = 'active') then raise exception 'CONNECTION_INACTIVE'; end if;
  if p_documents is null or exists(select 1 from unnest(p_documents) d where not exists(select 1 from public.dd_catalog c where c.id = d and c.insurer_id = p_insurer)) then raise exception 'INVALID_INPUT'; end if;
  insert into public.dd_documents(user_id, document_id, metadata)
    select actor, id, metadata from public.dd_catalog where insurer_id = p_insurer and id = any(p_documents)
    on conflict(user_id, document_id) do nothing;
  update public.dd_connections set last_sync_at = now() where user_id = actor and insurer_id = p_insurer;
end; $$;

create function public.dd_disconnect(p_insurer uuid) returns void
language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'UNAUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 0));
  update public.dd_connections set status = 'disconnected' where user_id = actor and insurer_id = p_insurer and status = 'active';
  if found then
    insert into public.dd_consent_events(user_id, insurer_id, action, locale, consent_text)
    values(actor, p_insurer, 'revoked', coalesce((select locale from public.dd_consent_events where user_id = actor and insurer_id = p_insurer and action = 'granted' order by created_at desc limit 1), 'de'), 'Demo connection revoked. Previously imported documents retained.');
  end if;
end; $$;

create function public.dd_reset() returns void
language plpgsql security definer set search_path = '' as $$
declare actor uuid := auth.uid();
begin
  if actor is null then raise exception 'UNAUTHORIZED'; end if;
  perform pg_advisory_xact_lock(hashtextextended(actor::text, 0));
  delete from public.dd_documents where user_id = actor;
  delete from public.dd_consent_events where user_id = actor;
  delete from public.dd_connections where user_id = actor;
end; $$;
revoke all on function public.dd_connect(uuid,text), public.dd_import(uuid,uuid[]), public.dd_disconnect(uuid), public.dd_reset() from public, anon;
grant execute on function public.dd_connect(uuid,text), public.dd_import(uuid,uuid[]), public.dd_disconnect(uuid), public.dd_reset() to authenticated;

